// Generated from integrations/n8n/src/nodes/compose-note.ts by integrations/n8n/build.mts. Edit the source, not this.

// src/lib/talent-intake/rules.ts
const { REF_PATTERN, INTAKE_SOURCES, JOB_ROLES, JOB_ROLE_SLUGS, isJobRole, ATTACHMENT_KINDS, ATTACHMENT_MIME, INTAKE_LIMITS, attachmentKeyPrefix, isAttachmentKeyFor, normaliseIndianMobile } = (() => {
  const REF_PATTERN = /^VS-J-[A-Z0-9]{6}$/;
  const INTAKE_SOURCES = {
      web_en: "en",
      web_hi: "hi",
      web_hinglish: "hinglish",
  };
  const JOB_ROLES = {
      "factory-helper": "Factory helper",
      packing: "Packing",
      "machine-operator": "Machine operator",
      warehouse: "Warehouse: loading, picking, packing",
      "forklift-operator": "Forklift operator",
      "data-entry-operator": "Data entry operator",
      housekeeping: "Housekeeping",
      "iti-trades": "ITI trades: welder, fitter, electrician",
      electrician: "Electrician",
      welder: "Welder",
      fitter: "Fitter",
  };
  const JOB_ROLE_SLUGS = Object.keys(JOB_ROLES);
  function isJobRole(value) {
      return typeof value === "string" && Object.hasOwn(JOB_ROLES, value);
  }
  const ATTACHMENT_KINDS = ["audio", "image", "document"];
  const ATTACHMENT_MIME = {
      audio: /^audio\/(webm|ogg|mp4|mpeg|aac|wav|x-m4a)(;.*)?$/,
      image: /^image\/(jpeg|png|webp)$/,
      document: /^application\/(pdf|msword|vnd\.openxmlformats-officedocument\.wordprocessingml\.document)$/,
  };
  const INTAKE_LIMITS = {
      maxAttachments: 8,
      maxTextLength: 4000,
      maxFileNameLength: 200,
      maxAudioSeconds: 180,
      maxBytes: { audio: 10 * 1024 * 1024, image: 10 * 1024 * 1024, document: 20 * 1024 * 1024 },
  };
  function attachmentKeyPrefix(ref, at) {
      const month = String(at.getUTCMonth() + 1).padStart(2, "0");
      return `intake/${at.getUTCFullYear()}/${month}/${ref}/`;
  }
  function isAttachmentKeyFor(key, ref) {
      return key.startsWith("intake/") && key.includes(`/${ref}/`);
  }
  function normaliseIndianMobile(input) {
      const digits = input.replace(/\D/g, "");
      if (/^[6-9]\d{9}$/.test(digits))
          return `+91${digits}`;
      if (/^91[6-9]\d{9}$/.test(digits))
          return `+${digits}`;
      if (/^0[6-9]\d{9}$/.test(digits))
          return `+91${digits.slice(1)}`;
      return null;
  }
  return { REF_PATTERN, INTAKE_SOURCES, JOB_ROLES, JOB_ROLE_SLUGS, isJobRole, ATTACHMENT_KINDS, ATTACHMENT_MIME, INTAKE_LIMITS, attachmentKeyPrefix, isAttachmentKeyFor, normaliseIndianMobile };
})();

const PAGES = {
    web_en: "English jobs page (en-IN)",
    web_hi: "हिंदी jobs page (hi-IN)",
    web_hinglish: "Hindi jobs page, Latin script (hi-Latn-IN)",
};
const KIND = { audio: "voice note", image: "photo", document: "document" };
async function main() {
    const s = $("Claim submission").first().json;
    const page = PAGES[s.source] ?? s.source;
    const lines = [`**Job seeker ${s.ref}** · ${page} · ${s.phone}`];
    if (s.role)
        lines.push(`**Asked about:** ${JOB_ROLES[s.role] ?? s.role}`);
    if (s.text)
        lines.push("", "**Their message:**", s.text);
    for (const [n, a] of s.attachments.entries()) {
        if (a.kind !== "audio")
            continue;
        const transcript = a.transcriptStatus === "done" && a.transcript
            ? a.transcript
            : "_Could not be transcribed. Listen to the attachment._";
        lines.push("", `**Voice note (file ${n + 1}), automatic transcript:**`, transcript);
    }
    if (s.attachments.length) {
        lines.push("", `**Files (${s.attachments.length}):** ${s.attachments
            .map((a, n) => `${n + 1}. ${KIND[a.kind] ?? "file"}${a.name ? ` (${a.name})` : ""}`)
            .join(" · ")}`);
    }
    return [{ json: { contactName: `Job seeker ${s.ref}`, note: lines.join("\n") } }];
}

return main.call(this);

